(function($){
'use strict';
var $root=$('.maintenance-developer-admin');if(!$root.length)return;
var cfg=window.OneIdMaintenanceDeveloperAdmin||{},api=$root.data('api'),csrf=$root.data('csrf'),stepUp=$root.data('step-up-url'),selectedReason='';
function esc(v){return $('<div>').text(v==null?'':v).html();}
function post(data){return $.ajax({type:'POST',url:api,dataType:'json',headers:{'X-CSRF-Token':csrf},data:data});}
function status(message,error){$('#maintenance_developer_status strong').text(message);$('#maintenance_developer_status').toggleClass('is-error',!!error);}
function failure(xhr){var r=xhr.responseJSON||{},code=String(r.code||'MAINTENANCE_ACCESS_UNAVAILABLE');if(xhr.status===403&&code.indexOf('STEP_UP_')===0){window.location.href=stepUp;return;}status(code==='MAINTENANCE_ACCESS_SCHEMA_UNAVAILABLE'?cfg.schemaUnavailable:code,true);}
function localValue(date){var pad=function(v){return String(v).padStart(2,'0');};return date.getFullYear()+'-'+pad(date.getMonth()+1)+'-'+pad(date.getDate())+'T'+pad(date.getHours())+':'+pad(date.getMinutes());}
function readableDate(value,utc){var raw=String(value||'').trim(),date=utc?new Date(raw.replace(' ','T').replace(/\.\d+$/,'')+'Z'):new Date(raw);if(Number.isNaN(date.getTime()))return raw;var language=String(document.documentElement.lang||'en').toLowerCase().indexOf('ms')===0?'ms-MY':'en-MY';return new Intl.DateTimeFormat(language,{timeZone:'Asia/Kuala_Lumpur',day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}).format(date);}
window.oneidMaintenanceDeveloperReadableDate=readableDate;
function generateReference(){var d=new Date(),pad=function(v){return String(v).padStart(2,'0');};return 'ONEID-MD-'+d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+'-'+pad(d.getHours())+pad(d.getMinutes());}
function defaults(){var now=new Date();now.setSeconds(0,0);$('#maintenance_developer_valid_from').val(localValue(now));$('#maintenance_developer_valid_until').val(localValue(new Date(now.getTime()+3600000)));$('#maintenance_developer_reference').val(generateReference());$('.maintenance-developer-duration button').removeClass('is-selected').filter('[data-hours="1"]').addClass('is-selected');}
function publicIdentity(row){var name=String(row.display_name||''),staff=String(row.staff_number||'');return{name:name,staff:staff,label:name+(staff?' ('+staff+')':'')};}
function load(){post({admin_list_maintenance_developer_access:'',query:''}).done(function(r){status(r.feature_enabled?cfg.enabled:cfg.disabled,false);var html='';$.each(r.data||[],function(_,g){var state=String(g.effective_status||g.grant_status||''),identity=publicIdentity(g),period=readableDate(g.valid_from,true)+' — '+readableDate(g.valid_until,true),metadata=identity.staff+' · '+period+' · '+String(g.change_reference||'');html+='<div class="maintenance-developer-row"><div class="maintenance-developer-row__identity"><strong>'+esc(identity.name)+'</strong><small title="'+esc(metadata)+'">'+esc(metadata)+'</small></div><div><span class="maintenance-developer-badge maintenance-developer-badge--'+state.toLowerCase()+'">'+esc(state)+'</span> ';if(String(g.grant_status)==='ACTIVE')html+='<button class="btn btn-xs btn-danger md-revoke" data-id="'+Number(g.grant_id)+'" data-version="'+Number(g.configuration_version)+'">'+esc(cfg.revoke)+'</button>';html+='</div></div>';});$('#maintenance_developer_grants').html(html||'<p>'+esc(cfg.noResults)+'</p>');}).fail(failure);}
function search(){post({admin_search_maintenance_developer_candidates:'',query:$('#maintenance_developer_query').val()}).done(function(r){var html='';$.each(r.data||[],function(_,u){var identity=publicIdentity(u);html+='<div class="maintenance-developer-row"><div><strong>'+esc(identity.name)+'</strong><small>'+esc(identity.staff)+' · '+esc(u.eligibility)+'</small></div>'+(u.eligible?'<button class="btn btn-sm btn-primary md-select" data-id="'+esc(u.u_id)+'" data-label="'+esc(identity.label)+'">'+esc(cfg.select)+'</button>':'')+'</div>';});$('#maintenance_developer_candidates').html(html||'<p>'+esc(cfg.noResults)+'</p>');}).fail(failure);}
function reason(){return selectedReason==='OTHER'?$.trim($('#maintenance_developer_reason').val()):selectedReason;}
function legacyReview(){var user=$('#maintenance_developer_user_id').val(),from=$('#maintenance_developer_valid_from').val(),until=$('#maintenance_developer_valid_until').val(),why=reason(),reference=$.trim($('#maintenance_developer_reference').val());if(!user||!from||!until||new Date(until)<=new Date(from)||why.length<10||reference.length<8){window.swal(cfg.reviewTitle,cfg.validation,'warning');return;}post({admin_grant_maintenance_developer_access:'',user_id:user,valid_from:from,valid_until:until,change_reason:why,change_reference:reference,confirmation:'GRANT MAINTENANCE ACCESS '+user}).done(function(r){window.swal(cfg.success,r.code+' · '+r.correlation_id,'success');$('#maintenance_developer_grant_card').prop('hidden',true);load();}).fail(failure);}
$(document).on('click','#maintenance_developer_refresh',load)
.on('click','#maintenance_developer_search',search)
.on('keydown','#maintenance_developer_query',function(e){if(e.key==='Enter'){e.preventDefault();search();}})
.on('click','.md-select',function(){var id=String($(this).data('id')),label=String($(this).attr('data-label')||'');$('#maintenance_developer_user_id').val(id);$('#maintenance_developer_selected').text(label);$('#maintenance_developer_grant_card').prop('hidden',false);selectedReason='Controlled maintenance access testing';$('.maintenance-developer-reason-options button').removeClass('is-selected').filter('[data-reason="'+selectedReason+'"]').addClass('is-selected');$('#maintenance_developer_reason_other').prop('hidden',true);defaults();})
.on('click','.maintenance-developer-duration button',function(){var hours=Number($(this).data('hours')),start=new Date($('#maintenance_developer_valid_from').val()||Date.now());$('#maintenance_developer_valid_until').val(localValue(new Date(start.getTime()+hours*3600000)));$(this).addClass('is-selected').siblings().removeClass('is-selected');})
.on('change','#maintenance_developer_valid_from,#maintenance_developer_valid_until',function(){$('.maintenance-developer-duration button').removeClass('is-selected');})
.on('click','.maintenance-developer-reason-options button',function(){selectedReason=String($(this).data('reason'));$(this).addClass('is-selected').siblings().removeClass('is-selected');$('#maintenance_developer_reason_other').prop('hidden',selectedReason!=='OTHER');if(selectedReason==='OTHER')$('#maintenance_developer_reason').focus();})
.on('click','#maintenance_developer_generate_reference',function(){$('#maintenance_developer_reference').val(generateReference());})
.on('click','#maintenance_developer_grant',legacyReview);
$(document).on('shown.bs.tab','a[href="#configuration_maintenance_developer"]',load);
})(jQuery);
